import type { ReactNode } from 'react'

type Props = {
  hero: ReactNode
  main: ReactNode
  panel?: ReactNode
  className?: string
}

export function DashboardLayout({ hero, main, panel, className }: Props) {
  return (
    <div className={`flex flex-col min-h-0 ${className ?? ''}`}>
      <div className="flex-shrink-0">{hero}</div>
      <div className={`flex-1 p-6 ${panel ? 'grid grid-cols-1 lg:grid-cols-2 gap-6' : ''}`}>
        {panel ? (
          <>
            <div className="min-h-0">{main}</div>
            <div className="min-h-0">{panel}</div>
          </>
        ) : (
          <div>{main}</div>
        )}
      </div>
    </div>
  )
}
